<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\OfferService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('OFFER_QUEUE_VIEW');$id=(int)($_GET['id']??0);$errors=[];$o=OfferService::operationsFind($id);if(!$o){http_response_code(404);exit('Offer not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$new=OfferService::revise($id,$_POST['amount']??0,(string)($_POST['currency']??'TZS'),['total_cost'=>$_POST['total_cost']??'','company_charges'=>$_POST['company_charges']??'','insurance'=>$_POST['insurance']??'','taxes'=>$_POST['taxes']??''],(int)Auth::user()['id']);header('Location: '.Url::to('operations/offer-view.php?id='.$new.'&revised=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$fx=OfferService::fxRate();$pageTitle='Offer '.$o['offer_ref'];require BASE_PATH.'/app/Views/layout/header.php';?>
<div class="page-head"><div><span class="eyebrow dark">Transport offer</span><h1><?=h($o['offer_thread_ref'].' · version '.$o['version_no'])?></h1><p><?=h($o['load_ref'].' · '.($o['carrier_company_name']?:$o['carrier_user_name']))?></p></div><span class="status-pill status-<?=h($o['offer_status'])?>"><?=h(str_replace('_',' ',$o['offer_status']))?></span></div><?php if(isset($_GET['revised'])):?><div class="success">Revised 24-hour offer sent.</div><?php endif;foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?>
<div class="dashboard-mosaic"><section class="card feature-card"><h3>Final price</h3><p class="money-display">TZS <?=h(number_format((float)$o['offered_amount_tzs'],2))?></p><p class="money-secondary">USD <?=h(number_format((float)$o['offered_amount_usd'],2))?></p><div class="price-detail"><strong>Price explanation</strong><p><?=nl2br(h($o['price_breakdown']?:'No price explanation'))?></p></div></section><section class="card"><h3>Assigned resource</h3><p><strong><?=h($o['registration_number'].' · '.$o['make_name'].' '.$o['model_name'])?></strong></p><p><?=h('Driver '.$o['driver_name'])?></p></section><section class="card"><h3>Carrier response</h3><p>Counter: <strong><?=h($o['counter_amount_tzs']!==null?'TZS '.number_format((float)$o['counter_amount_tzs'],2):'—')?></strong></p><p><?=nl2br(h($o['response_note']?:'No response note'))?></p><p class="timestamp">Expires <?=h($o['expires_at'])?> UTC</p></section></div>
<?php if($o['offer_status']==='countered'&&Auth::can('OFFER_REVISE')):?><form method="post" class="card feature-card offer-revision" data-fx-rate="<?=h($fx)?>"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><h2>Send revised offer</h2><div class="pricing-entry"><div class="field"><label>Currency</label><select name="currency" class="offer-currency"><option value="TZS">TZS</option><option value="USD">USD</option></select></div><div class="field"><label>Final offer amount</label><input class="money-input offer-amount" inputmode="decimal" name="amount" required><span class="field-help offer-equivalent">Enter an amount to see the equivalent.</span></div></div><div class="form-grid price-breakdown"><div class="field"><label>Transport cost</label><input class="money-input" inputmode="decimal" name="total_cost"></div><div class="field"><label>Company charges</label><input class="money-input" inputmode="decimal" name="company_charges"></div><div class="field"><label>Insurance</label><input class="money-input" inputmode="decimal" name="insurance"></div><div class="field"><label>Taxes</label><input class="money-input" inputmode="decimal" name="taxes"></div></div><button class="button">Send revised offer</button></form><?php endif;?><p><a href="<?=h(Url::to('operations/offers.php'))?>">← Back to offers</a></p><?php require BASE_PATH.'/app/Views/layout/footer.php';
